const named: Record<string,string> = {quot: '"', apos: "'", gt: '>', lt: '<', amp: '&'}
return input.replace(/&(?:#x([0-9A-Fa-f]+)|#([0-9]+)|(quot|apos|lt|gt|amp));/g,
