  // to marker can still be the from cell. Include the actual frame, walking
  // the same visible column/row sizes the print layout uses. Explicit print
  // areas and Print Selection bypass usedArea and keep their intended clip.
  const endIndex = (start: number, span: number, size: (index: number) => number, last: number): number => {
    let index = start
    while (index < last) {
      span -= size(index)
      if (span <= 0) break
      index += 1
    }
    return index
  }
